import{_ as a,o as t,c as i,ae as s}from"./chunks/framework.RRduUuAx.js";const u=JSON.parse('{"title":"SLSA Build Attestation","description":"","frontmatter":{},"headers":[],"relativePath":"slsa.md","filePath":"slsa.md"}'),r={name:"slsa.md"};function o(l,e,n,h,c,d){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="slsa-build-attestation" tabindex="-1">SLSA Build Attestation <a class="header-anchor" href="#slsa-build-attestation" aria-label="Permalink to &quot;SLSA Build Attestation&quot;">​</a></h1><p>This repository publishes build provenance for release artifacts in accordance with <a href="https://slsa.dev" target="_blank" rel="noreferrer">SLSA (Supply-chain Levels for Software Artifacts)</a> Build specifications. SLSA provenance allows downstream consumers to verify that an artifact was built from the expected source repository, at the expected commit, by the expected build platform.</p><h2 id="target-level" tabindex="-1">Target Level <a class="header-anchor" href="#target-level" aria-label="Permalink to &quot;Target Level&quot;">​</a></h2><p><strong>Current target: SLSA Build L2 (achieved today)</strong></p><p>The release pipeline is hosted on GitHub Actions, an isolated build platform that is owned and administered by GitHub. Provenance is generated automatically for every published release using <a href="https://github.com/slsa-framework/slsa-github-generator" target="_blank" rel="noreferrer"><code>slsa-framework/slsa-github-generator</code></a> and the <code>attest-build-provenance</code> action. Provenance is signed by a GitHub- hosted OIDC token and stored in the <a href="https://docs.github.com/en/security/supply-chain-security/artifact-attestations" target="_blank" rel="noreferrer">GitHub Artifact Attestations</a> log alongside the artifact.</p><h2 id="workflow" tabindex="-1">Workflow <a class="header-anchor" href="#workflow" aria-label="Permalink to &quot;Workflow&quot;">​</a></h2><p>The CI workflow lives at <a href="../.github/workflows/release-attestation.yml"><code>.github/workflows/release-attestation.yml</code></a> and is triggered:</p><ul><li>Automatically on every <code>release: published</code> event.</li><li>Manually via <code>workflow_dispatch</code> for ad-hoc provenance generation.</li></ul><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> attestation</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">artifac</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --owner</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> KooshaPari</span></span></code></pre></div><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><a href="https://slsa.dev" target="_blank" rel="noreferrer">SLSA Framework</a></li><li><a href="https://github.com/slsa-framework/slsa-github-generator" target="_blank" rel="noreferrer"><code>slsa-framework/slsa-github-generator</code></a></li><li><a href="https://docs.github.com/en/security/supply-chain-security/artifact-attestations" target="_blank" rel="noreferrer">GitHub Artifact Attestations</a></li></ul>',12)])])}const f=a(r,[["render",o]]);export{u as __pageData,f as default};
